receipt-line.correct:
def receipt_line(item, quantity, price):
    total = quantity * price
    return f"{quantity} x {item} = Rs {total}"

receipt-line.half_fixed:
def receipt_line(item, quantity, price):
    total = quantity * price
    return str(quantity) + " x " + item + " = Rs " + total

receipt-line.spacing:
def receipt_line(item, quantity, price):
    total = quantity * price
    return f"{quantity}x {item} = Rs {total}"

fizzbuzz.correct:
def fizzbuzz(n):
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(str(i))
    return result

